<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:9px;color:#1e293b}h1{color:#1d4ed8}table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:6px}th{background:#1d4ed8;color:white}.right{text-align:right}.footer{position:fixed;bottom:0;width:100%;border-top:1px solid #ddd;padding-top:5px}</style></head><body><h1>{{ \App\Support\SystemSettings::get('system_name','Phone Shop POS') }} — Cheque Report</h1><p>Generated {{ now()->format('Y-m-d H:i') }} by {{ auth()->user()->name }}</p><table><thead><tr><th>Reference</th><th>Type</th><th>Cheque</th><th>Date</th><th>Party</th><th>Bank</th><th>Amount</th><th>Hold</th><th>Status</th></tr></thead><tbody>@foreach($cheques as $c)<tr><td>{{ $c->cheque_reference }}</td><td>{{ ucfirst($c->cheque_type) }}</td><td>{{ $c->cheque_number }}</td><td>{{ $c->cheque_date->format('Y-m-d') }}</td><td>{{ $c->customer?->name??$c->supplier?->name??$c->payee_name }}</td><td>{{ $c->bank_name }}</td><td class="right">{{ number_format($c->amount,2) }}</td><td class="right">{{ number_format($c->hold_amount,2) }}</td><td>{{ $c->display_status }}</td></tr>@endforeach</tbody><tfoot><tr><th colspan="6">Total</th><th class="right">{{ number_format($cheques->sum('amount'),2) }}</th><th class="right">{{ number_format($cheques->sum('hold_amount'),2) }}</th><th></th></tr></tfoot></table><div class="footer">Cheque Management Report · {{ config('app.name') }}</div></body></html>
